svg.script:
(async function () {
  const image = document.getElementById('skinImage');
  const status = document.getElementById('status');
  try {
    const response = await fetch('skin-professional-approved.b64.txt?v=20260731-final-source', {cache: 'no-store'});
    if (!response.ok) throw new Error('HTTP ' + response.status);
    const base64 = (await response.text()).replace(/\s+/g, '');
    if (!base64.startsWith('/9j/') || base64.length < 10000 || !base64.endsWith('/9k=')) {
      throw new Error('Invalid JPEG Base64 payload');
    }
    image.setAttribute('href', 'data:image/jpeg;base64,' + base64);
    status.setAttribute('display', 'none');
  } catch (error) {
    status.textContent = 'Skin Professional';
    console.error(error);
  }
}());
